    "fragment ProfileUserFields on User {\n  id\n  username\n  email\n  isVerified\n  tiktokOpenId\n  authProviders {\n    local\n    google\n    facebook\n    apple\n  }\n  profile {\n    firstName\n    lastName\n    avatar\n    bio\n    website\n  }\n  followerCount\n  followingCount\n  postCount\n  totalViews\n  totalLikes\n  isFollowedByMe\n}\n\nfragment ProfilePostFields on Content {\n  id\n  slug\n  type\n  title\n  caption\n  createdAt\n  price {\n    amount\n    currency\n    negotiable\n  }\n  location {\n    county\n    subregion\n    placeName\n  }\n  stats {\n    views\n    likes\n    saves\n    shares\n    comments\n  }\n  media {\n    mediaType\n    thumbnailUrl\n    url\n    sortOrder\n    muxMeta {\n      playbackId\n      thumbnailUrl\n      aspectRatio\n    }\n    r2Variants {\n      variant\n      url\n      width\n      height\n    }\n  }\n}\n\nquery GetMyProfile {\n  me {\n    ...ProfileUserFields\n  }\n}\n\nquery GetUserProfile($username: String!) {\n  userProfile(username: $username) {\n    ...ProfileUserFields\n  }\n}\n\nquery GetUserPosts($userId: String!, $limit: Int, $afterId: String, $sort: DiscoverySort) {\n  userPosts(userId: $userId, limit: $limit, afterId: $afterId, sort: $sort) {\n    hasMore\n    nextCursor\n    posts {\n      ...ContentCardFields\n    }\n  }\n}\n\nquery GetMyPosts($limit: Int, $afterId: String) {\n  myPosts(limit: $limit, afterId: $afterId) {\n    hasMore\n    nextCursor\n    posts {\n      ...ProfilePostFields\n    }\n  }\n}\n\nquery GetMySavedContent($limit: Int, $afterId: String) {\n  mySavedContent(limit: $limit, afterId: $afterId) {\n    hasMore\n    nextCursor\n    items {\n      ...ContentCardFields\n    }\n  }\n}\n\nquery GetMyAnalytics {\n  myAnalytics {\n    last30DaysViews\n    last30DaysSaves\n    last30DaysFollowers\n    topPost {\n      contentId\n      views\n      saves\n    }\n    viewsByDay {\n      date\n      views\n    }\n  }\n}\n\nquery CheckUsernameAvailability($username: String!) {\n  checkUsername(username: $username) {\n    username\n    available\n  }\n}\n\nmutation UpdateMyProfile($input: UpdateProfileInput!) {\n  updateProfile(input: $input) {\n    ...ProfileUserFields\n  }\n}\n\nmutation RecordProfileVisit($userId: String!) {\n  recordProfileVisit(userId: $userId)\n}\n\nfragment VisitorFields on User {\n  id\n  username\n  profile {\n    firstName\n    lastName\n    avatar\n  }\n  isFollowedByMe\n  isFollowingMe\n}\n\nquery MyProfileVisitorsPreview($limit: Int) {\n  myProfileVisitorsPreview(limit: $limit) {\n    totalCount\n    recent {\n      ...VisitorFields\n    }\n  }\n}\n\nquery MyProfileVisitors($limit: Int, $after: String) {\n  myProfileVisitors(limit: $limit, after: $after) {\n    totalCount\n    hasMore\n    nextCursor\n    visitors {\n      ...VisitorFields\n    }\n  }\n}\n\nquery MyFollowers($limit: Int, $after: String) {\n  myFollowers(limit: $limit, after: $after) {\n    totalCount\n    hasMore\n    nextCursor\n    users {\n      ...VisitorFields\n    }\n  }\n}\n\nquery GetMyTiktokVideos($cursor: String) {\n  myTiktokVideos(cursor: $cursor) {\n    videos {\n      id\n      title\n      coverImageUrl\n      shareUrl\n      duration\n      createTime\n      viewCount\n      likeCount\n    }\n    nextCursor\n    hasMore\n  }\n}\n\nquery GetMyTiktokImports {\n  myTiktokImports {\n    id\n    url\n    status\n    title\n    thumbnailUrl\n    muxPlaybackId\n    hlsUrl\n    errorMessage\n    createdAt\n  }\n}\n\nquery GetMyTiktokImportsPaged($limit: Int, $after: String) {\n  myTiktokImportsPaged(limit: $limit, after: $after) {\n    hasMore\n    nextCursor\n    items {\n      id\n      url\n      status\n      title\n      thumbnailUrl\n      muxPlaybackId\n      hlsUrl\n      errorMessage\n      createdAt\n    }\n  }\n}\n\nmutation BatchImportTiktokVideos($shareUrls: [String!]!) {\n  batchImportTiktokVideos(shareUrls: $shareUrls) {\n    batchId\n    queued\n    skipped\n    downloads {\n      id\n      url\n      status\n      title\n      thumbnailUrl\n      errorMessage\n    }\n  }\n}\n\nquery GetTiktokConnectStatus {\n  me {\n    id\n    authProviders {\n      tiktok\n    }\n  }\n}\n\nmutation GetTiktokConnectUrl($returnUrl: String) {\n  tiktokConnectUrl(returnUrl: $returnUrl)\n}\n\nmutation ChangePassword($input: ChangePasswordInput!) {\n  changePassword(input: $input) {\n    accessToken\n    refreshToken\n    user {\n      id\n    }\n  }\n}\n\nmutation DeleteMyAccount($password: String) {\n  deleteMyAccount(password: $password)\n}\n\nfragment AppRatingFields on AppRating {\n  id\n  stars\n  comment\n  updatedAt\n}\n\nquery MyAppRating {\n  myAppRating {\n    ...AppRatingFields\n  }\n}\n\nquery AppRatingSummary {\n  appRatingSummary {\n    average\n    total\n    distribution\n  }\n}\n\nmutation SubmitAppRating($input: SubmitAppRatingInput!) {\n  submitAppRating(input: $input) {\n    ...AppRatingFields\n  }\n}": types.ProfileUserFieldsFragmentDoc,
